	@BeforeEach
	public void insertStarWarsGraph() {
		ModelBuilder graph = new ModelBuilder();
		addCharacter(graph, LUKE, TATOOINE);
		addCharacter(graph, ANAKIN, TATOOINE);
		addCharacter(graph, REY, JAKKU);

		addMaster(graph, OBI_WAN, "Obi-Wan Kenobi", LIGHT_SIDE);
		addMaster(graph, YODA, "Yoda", LIGHT_SIDE);
		addMaster(graph, DARTH_SIDIOUS, "Darth Sidious", DARK_SIDE);
		addMaster(graph, QUI_GON, "Qui-Gon Jinn", LIGHT_SIDE);

		graph.subject(LUKE).add(TRAINED_BY, OBI_WAN).add(TRAINED_BY, YODA);
		graph.subject(ANAKIN).add(TRAINED_BY, OBI_WAN).add(TRAINED_BY, DARTH_SIDIOUS);

		rdf4JTemplate.consumeConnection(connection -> connection.add(graph.build()));
	}

	@Test
	public void innerJoinReturnsOnlyCharactersWithMasters() {
		Map<IRI, Set<IRI>> result = JoinQueryBuilder.of(TRAINED_BY)
				.sourceEntityConstraints(character -> character.isA(FORCE_USER))
				.targetEntityConstraints(master -> master.isA(MASTER))
				.innerJoin()
				.build()
				.evaluationBuilder(rdf4JTemplate)
				.asOneToMany();

		assertEquals(
				Map.of(
						LUKE, Set.of(OBI_WAN, YODA),
						ANAKIN, Set.of(OBI_WAN, DARTH_SIDIOUS)),
				result);
	}

	@Test
	public void leftOuterJoinKeepsCharacterWithoutMaster() {
		Map<IRI, Set<IRI>> result = JoinQueryBuilder.of(TRAINED_BY)
				.sourceEntityConstraints(character -> character.isA(FORCE_USER))
				.targetEntityConstraints(master -> master.isA(MASTER))
				.leftOuterJoin()
				.build()
				.evaluationBuilder(rdf4JTemplate)
				.asOneToMany();

		assertEquals(
				Map.of(
						LUKE, Set.of(OBI_WAN, YODA),
						ANAKIN, Set.of(OBI_WAN, DARTH_SIDIOUS),
						REY, Set.of()),
				result);
	}

	@Test
	public void rightOuterJoinKeepsMasterWithoutApprentice() {
		Set<IdPair> result = JoinQueryBuilder.of(TRAINED_BY)
				.sourceEntityConstraints(character -> character.isA(FORCE_USER))
				.targetEntityConstraints(master -> master.isA(MASTER))
				.rightOuterJoin()
				.build()
				.evaluationBuilder(rdf4JTemplate)
				.asIdPairList()
				.stream()
				.map(pair -> new IdPair(pair[0], pair[1]))
				.collect(Collectors.toSet());

		assertEquals(
				Set.of(
						new IdPair(LUKE, OBI_WAN),
						new IdPair(LUKE, YODA),
						new IdPair(ANAKIN, OBI_WAN),
						new IdPair(ANAKIN, DARTH_SIDIOUS),
						new IdPair(null, QUI_GON)),
				result);
	}

