	@Test
	public void inversePropertyPathFindsApprenticesByMaster() {
		Map<IRI, Set<IRI>> result = JoinQueryBuilder.of(path -> path.pred(TRAINED_BY).inv())
				.sourceEntityConstraints(master -> master.isA(MASTER))
				.targetEntityConstraints(character -> character.isA(FORCE_USER))
				.innerJoin()
				.build()
				.evaluationBuilder(rdf4JTemplate)
				.asOneToMany();

		assertEquals(
				Map.of(
						OBI_WAN, Set.of(LUKE, ANAKIN),
						YODA, Set.of(LUKE),
						DARTH_SIDIOUS, Set.of(ANAKIN)),
				result);
	}

	@Test
	public void rowMapperFactoryCreatesOneInstancePerBindingSet() {
		RowMapperFactoryBase<MutableCharacter> factory = new RowMapperFactoryBase<>(MutableCharacter::new) {
			@Override
			protected MutableCharacter setMembers(BindingSet bindings, Variable idVariable, MutableCharacter instance) {
				instance.id = (IRI) bindings.getValue(idVariable.getVarName());
				return instance;
			}
		};
		BindingSetMapper<MutableCharacter> mapper = factory.apply(var("id"));

		MapBindingSet lukeBinding = new MapBindingSet();
		lukeBinding.addBinding("id", LUKE);
		MapBindingSet anakinBinding = new MapBindingSet();
		anakinBinding.addBinding("id", ANAKIN);

		MutableCharacter luke = mapper.apply(lukeBinding);
		MutableCharacter anakin = mapper.apply(anakinBinding);

		assertEquals(LUKE, luke.id);
		assertEquals(ANAKIN, anakin.id);
		assertNotSame(luke, anakin);
	}
	private static void assertRightOuterJoinRejected(String operation, Executable executable) {
		IllegalStateException exception = assertThrows(IllegalStateException.class, executable);
		assertEquals(
				operation
						+ " cannot be used with RIGHT_OUTER joins because unmatched targets have no source entity key.",
				exception.getMessage());
	}
	private static void addCharacter(ModelBuilder graph, IRI character, IRI homeworld) {
		graph.subject(character).add(RDF.TYPE, FORCE_USER).add(HOMEWORLD, homeworld);
	}

	private static void addMaster(ModelBuilder graph, IRI master, String name, IRI affiliation) {
		graph.subject(master)
				.add(RDF.TYPE, MASTER)
				.add(RDFS.LABEL, name)
				.add(AFFILIATION, affiliation);
	}

	private static IRI iri(String localName) {
		return SimpleValueFactory.getInstance().createIRI(NAMESPACE, localName);
	}

	private static final class MutableCharacter {
		private IRI id;
	}

	private record IdPair(IRI source, IRI target) {
	}

	private record MasterRecord(IRI id, String name) {
	}
